plugins {
    id 'java'
    id 'application'
}

sourceCompatibility = JavaVersion.VERSION_17
targetCompatibility = JavaVersion.VERSION_17

repositories {
    mavenCentral()
}

def gdxVersion = '1.14.2'

dependencies {
    implementation "com.badlogicgames.gdx:gdx:${gdxVersion}"
    implementation "com.badlogicgames.gdx:gdx-backend-headless:${gdxVersion}"
    implementation "com.badlogicgames.gdx:gdx-platform:${gdxVersion}:natives-desktop"
}

application {
    mainClass = 'com.scenebaker.SceneBakerLauncher'
}

tasks.named('run') {
    standardInput = System.in
    if (project.hasProperty('args')) {
        // handled by --args on the command line automatically
    }
}

package com.scenebaker;

/**
 * Abstract base class for all scene-graph nodes.
 */
public abstract class Node {
    /** class tag / discriminator, e.g. "group", "sprite", "light", "trigger" */
    public String type;

    public String name;

    /** Only meaningful during deserialization/pruning; not part of output. */
    public boolean enabled = true;

    public float lx = 0f;
    public float ly = 0f;
    public float ls = 1f;

    /** Assigned during the id-assignment pass. */
    public int id;

    /** Computed during the transform pass. */
    public float absX;
    public float absY;
    public float absScale;

    public abstract String kindTag();
}

package com.scenebaker;

import com.badlogic.gdx.utils.Array;

public class GroupNode extends Node {
    public Array<Node> children = new Array<>();

    @Override
    public String kindTag() {
        return "group";
    }
}

package com.scenebaker;

import com.badlogic.gdx.utils.IntArray;

public class SpriteNode extends Node {
    public String region;
    public int z;
    public IntArray frames = new IntArray();

    @Override
    public String kindTag() {
        return "sprite";
    }
}

package com.scenebaker;

public class LightNode extends Node {
    public String color;
    public float intensity;

    @Override
    public String kindTag() {
        return "light";
    }
}

package com.scenebaker;

import com.badlogic.gdx.utils.IntArray;
import com.badlogic.gdx.utils.ObjectMap;

public class TriggerNode extends Node {
    public String event;
    public ObjectMap<String, String> params = new ObjectMap<>();
    public IntArray targets = new IntArray();

    @Override
    public String kindTag() {
        return "trigger";
    }
}

