	private Serializer defaultSerializer;
	private final ObjectMap> typeToFields = new ObjectMap(); private final ObjectMap tagToClass = new ObjectMap(); private final ObjectMap classToTag = new ObjectMap(); private final ObjectMap classToSerializer = new ObjectMap(); private final ObjectMap classToDefaultValues = new ObjectMap(); private final Object[] equals1 = {null}, equals2 = {null}; public Json () { outputType = OutputType.minimal; } public Json (OutputType outputType) { this.outputType = outputType; } /** When true, fields in the JSON that are not found on the class will not throw a {@link SerializationException}. Default is * false. */ public void setIgnoreUnknownFields (boolean ignoreUnknownFields) { this.ignoreUnknownFields = ignoreUnknownFields; } public boolean getIgnoreUnknownFields () { return ignoreUnknownFields; } /** When true, fields with the {@link Deprecated} annotation will not be read or written. Default is false. * @see #setReadDeprecated(boolean) * @see #setDeprecated(Class, String, boolean) */ public void setIgnoreDeprecated (boolean ignoreDeprecated) { this.ignoreDeprecated = ignoreDeprecated; } /** When true, fields with the {@link Deprecated} annotation will be read (but not written) when * {@link #setIgnoreDeprecated(boolean)} is true. Default is false. * @see #setDeprecated(Class, String, boolean) */ public void setReadDeprecated (boolean readDeprecated) { this.readDeprecated = readDeprecated; } /** Default is {@link OutputType#minimal}. * @see JsonWriter#setOutputType(OutputType) */ public void setOutputType (OutputType outputType) { this.outputType = outputType; } /** Default is false. * @see JsonWriter#setQuoteLongValues(boolean) */ public void setQuoteLongValues (boolean quoteLongValues) { this.quoteLongValues = quoteLongValues; } /** When true, {@link Enum#name()} is used to write enum values. When false, {@link Enum#toString()} is used which may not be * unique. Default is true. */ public void setEnumNames (boolean enumNames) { this.enumNames = enumNames; } /** Sets a tag