entType = elementType; } /** The specified field will be treated as if it has or does not have the {@link Deprecated} annotation. * @see #setIgnoreDeprecated(boolean) * @see #setReadDeprecated(boolean) */ public void setDeprecated (Class type, String fieldName, boolean deprecated) { FieldMetadata metadata = getFields(type).get(fieldName); if (metadata == null) throw new SerializationException("Field not found: " + fieldName + " (" + type.getName() + ")"); metadata.deprecated = deprecated; } /** When true, fields are sorted alphabetically when written, otherwise the source code order is used. Default is false. * @see #sortFields(Class, Array) */ public void setSortFields (boolean sortFields) { this.sortFields = sortFields; } /** Called to sort the fields for a class. Default implementation sorts alphabetically if {@link #setSortFields(boolean)} is * true. */ protected void sortFields (Class type, Array fieldNames) { if (sortFields) fieldNames.sort(); } private OrderedMap getFields (Class type) { OrderedMap fields = typeToFields.get(type); if (fields != null) return fields; Array classHierarchy = new Array(); Class nextClass = type; while (nextClass != Object.class) { classHierarchy.add(nextClass); nextClass = nextClass.getSuperclass(); } ArrayList allFields = new ArrayList(); for (int i = classHierarchy.size - 1; i >= 0; i--) Collections.addAll(allFields, ClassReflection.getDeclaredFields(classHierarchy.get(i))); OrderedMap nameToField = new OrderedMap(allFields.size()); for (int i = 0, n = allFields.size(); i < n; i++) { Field field = allFields.get(i); if (field.isTransient()) continue; if (field.isStatic()) continue; if (field.isSynthetic()) continue; if (!field.isAccessible()) { try { field.setAccessible(true); } catch (RuntimeException ex) { continue; } } nameToField.put(field.getName(), new FieldMetadata(field)); } sortFields(type, nameToField.keys); typeToFields.put(type, nameToField); return nameToField; } public String toJson (@Null Object object) { return to